const input = $input.first().json;

// Detect source: tester UI vs WAHA
let source, chatId, messageBody, isFromMe, messageType;

// Check if it's the tester format (in body)
if (input.body?.message !== undefined && input.body?.session_id !== undefined) {
  // Tester UI format: { body: { message, session_id } }
  source = 'tester';
  chatId = input.body.session_id;
  messageBody = input.body.message;
  isFromMe = false;
  messageType = 'chat';
} 
// Check if it's WAHA format
else if (input.payload) {
  // WAHA format: { event, session, payload: { from, body, ... } }
  source = 'waha';
  chatId = input.payload.from;
  messageBody = input.payload.body || '';
  isFromMe = input.payload.fromMe || false;
  messageType = input.payload.type || 'chat';
} 
// Unknown shape
else {
  return [{ json: { skip: true, reason: 'Unknown payload format', rawInput: input } }];
}

// Basic guardrails (equivalent to v2's Filter Real Messages)
if (messageType !== 'chat' || !messageBody || !messageBody.trim()) {
  return [{ json: { skip: true, reason: 'not a chat message or empty body' } }];
}

return [{
  json: { source, chatId, messageBody, isFromMe, messageType }
}];

// ═══ ENTRY POINT DETECTION ═══
const input = $input.first().json;
const isLoopBack = input.contents !== undefined;

let workflowState;

if (isLoopBack) {
  workflowState = {
    chatId: input.chatId,
    userMessage: input.userMessage,
    source: input.source,
    contents: input.contents,
    iteration: input.iteration || 1
  };
} else {
  const prev = $('Normalize Payload').first().json;
  const historyRows = $('Fetch History').all().map(i => i.json);

  const contents = [];
  const recentHistory = [...historyRows].reverse().slice(0, 6);
  for (const turn of recentHistory) {
    if (turn.role && turn.content) {
      contents.push({ role: turn.role, parts: [{ text: turn.content }] });
    }
  }
  contents.push({ role: "user", parts: [{ text: prev.messageBody }] });

  workflowState = {
    chatId: prev.chatId,
    userMessage: prev.messageBody,
    source: prev.source,
    contents: contents,
    iteration: 0
  };
}

const GEMINI_API_KEY = 'YOUR_GEMINI_API_KEY';
const MAX_ITERATIONS = 5;

// Safety checks
if (workflowState.iteration >= MAX_ITERATIONS) {
  return [{
    json: {
      mode: 'FINAL_REPLY',
      ...workflowState,
      reply: "I'm having trouble. Please type *menu* to start over."
    }
  }];
}

if (!workflowState.contents || workflowState.contents.length === 0) {
  return [{
    json: {
      mode: 'FINAL_REPLY',
      reply: "Something went wrong. Please type *hi* to begin."
    }
  }];
}

// ═══ DATABASE CONNECTION ═══
const { Pool } = require('pg');
const pool = new Pool({
  host: 'postgres',
  port: 5432,
  database: 'waltonmarket',
  user: 'walton',
  password: 'REDACTED'
});

// ═══ TOOL DEFINITIONS ═══
const tools = [{
  functionDeclarations: [
    {
      name: "send_main_menu",
      description: "Show main menu. Use when customer greets (hi/hello/assalam) or types 'menu'.",
      parameters: { type: "object", properties: {} }
    },
    {
      name: "search_products",
      description: "Search products by name or category. Use when customer asks about specific products.",
      parameters: {
        type: "object",
        properties: {
          query: { type: "string", description: "Search query (empty for featured products)" }
        }
      }
    },
    {
      name: "get_product_details",
      description: "Get product details by ID.",
      parameters: {
        type: "object",
        properties: {
          product_id: { type: "integer" }
        },
        required: ["product_id"]
      }
    },
    {
      name: "view_cart",
      description: "Show cart contents.",
      parameters: { type: "object", properties: {} }
    },
    {
      name: "add_to_cart",
      description: "Add product to cart.",
      parameters: {
        type: "object",
        properties: {
          product_id: { type: "integer" },
          quantity: { type: "integer" }
        },
        required: ["product_id"]
      }
    },
    {
      name: "remove_from_cart",
      description: "Remove product from cart.",
      parameters: {
        type: "object",
        properties: {
          product_id: { type: "integer" }
        },
        required: ["product_id"]
      }
    },
    {
      name: "clear_cart",
      description: "Empty cart completely.",
      parameters: { type: "object", properties: {} }
    },
    {
      name: "checkout",
      description: "Complete order with customer details.",
      parameters: {
        type: "object",
        properties: {
          customer_name: { type: "string" },
          phone: { type: "string" },
          address: { type: "string" },
          city: { type: "string" }
        },
        required: ["customer_name", "phone", "address", "city"]
      }
    },
    {
      name: "get_order_status",
      description: "Check order status.",
      parameters: {
        type: "object",
        properties: {
          phone: { type: "string" }
        }
      }
    },
    {
      name: "start_quotation",
      description: "Start installation quote process.",
      parameters: { type: "object", properties: {} }
    },
    {
      name: "get_company_info",
      description: "Get company information (location, payment, delivery).",
      parameters: {
        type: "object",
        properties: {
          info_type: { type: "string", enum: ["location", "contact", "payment", "delivery", "all"] }
        },
        required: ["info_type"]
      }
    },
    {
      name: "escalate_to_human",
      description: "Transfer to human support.",
      parameters: { type: "object", properties: {} }
    }
  ]
}];

// ═══ SYSTEM INSTRUCTION ═══
const systemInstruction = `You are Arik, WaltonMarket's WhatsApp assistant for smart home products in Pakistan.

RULES:
1. ALWAYS call tools - never generate responses without tools
2. Match customer's language: English→English, Roman Urdu→Roman Urdu
3. After tool returns data, wrap it naturally in customer's language
4. Keep responses under 500 chars unless showing product lists
5. Use *bold* for products, Rs. for prices

LANGUAGE EXAMPLES:
- Customer says "Hi" → respond in English: "Welcome to WaltonMarket!"
- Customer says "assalam" → respond in Roman Urdu: "Walaikum Assalam!"
- Customer says "show switches" → English: "Here are our switches:"
- Customer says "switch dikhao" → Roman Urdu: "Yeh rahe switches:"

CONTEXT:
- If you showed products #1-5 and customer says "first one" or "pehla wala" or "1", they want product #1 from the list → call get_product_details or add_to_cart with that product_id
- If customer says "add to cart" after seeing a product, add that product
- Guide next steps naturally`;

// ═══ TOOL EXECUTOR ═══
async function executeTool(toolName, toolArgs, chatId) {
  try {
    switch (toolName) {
      case "send_main_menu":
        return `📋 *WaltonMarket Main Menu*

1️⃣ View Catalogue
2️⃣ Order Status
3️⃣ Installation Quote
4️⃣ Talk to Human

Select a number or tell me what you need.`;

      case "search_products": {
        const query = (toolArgs.query || '').trim();
        if (!query) {
          const { rows } = await pool.query('SELECT id, product_name, price FROM products LIMIT 5');
          let result = "Featured products:\n\n";
          rows.forEach((p, i) => result += `${i+1}. *${p.product_name}* — Rs. ${p.price}\n`);
          return result + "\nLooking for something specific?";
        }

        const embResp = await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-embedding-2:embedContent',
          headers: { 'Content-Type': 'application/json' },
          qs: { key: GEMINI_API_KEY },
          body: { model: "models/gemini-embedding-2", content: { parts: [{ text: query }] } },
          timeout: 10000
        });

        const embedding = embResp.embedding.values;
        const embStr = `[${embedding.join(',')}]`;

        const { rows } = await pool.query(
          `SELECT id, product_name, price FROM products 
           WHERE embedding IS NOT NULL 
           ORDER BY embedding <-> $1::vector LIMIT 5`,
          [embStr]
        );

        if (rows.length === 0) return `No products found for "${query}". Try a different search?`;

        let result = `Found ${rows.length} products:\n\n`;
        rows.forEach((p, i) => result += `${i+1}. *${p.product_name}* — Rs. ${p.price}\n`);
        return result + "\nNeed details or want to add to cart?";
      }

      case "get_product_details": {
        const { rows } = await pool.query(
          `SELECT product_name, price, description, category, compatibility, stock FROM products WHERE id = $1`,
          [toolArgs.product_id]
        );
        if (rows.length === 0) return "Product not found.";

        const p = rows[0];
        let result = `*${p.product_name}*\n\n💰 Price: Rs. ${p.price}\n`;
        if (p.category) result += `📦 Category: ${p.category}\n`;
        if (p.compatibility) result += `🔌 Compatible: ${p.compatibility}\n`;
        if (p.stock) result += `📊 Stock: ${p.stock}\n`;
        if (p.description) result += `\n${p.description}\n`;
        return result + "\nAdd to cart?";
      }

      case "view_cart": {
        const { rows } = await pool.query('SELECT cart FROM v3_sessions WHERE chat_id = $1', [chatId]);
        let cart = rows.length > 0 ? rows[0].cart : [];
        if (!Array.isArray(cart) || cart.length === 0) {
          return "🛒 Your cart is empty.\n\nSearch for products or type *menu*.";
        }

        let total = 0;
        let result = "🛒 *Your Cart:*\n\n";
        cart.forEach((item, i) => {
          const itemTotal = item.price * item.quantity;
          total += itemTotal;
          result += `${i+1}. *${item.product_name}*\n   Qty: ${item.quantity} × Rs. ${item.price} = Rs. ${itemTotal}\n\n`;
        });
        result += `━━━━━━━━━━━━━━━━━━━━\n*Total: Rs. ${total}*\n\n`;
        return result + "Ready to checkout? Provide name, phone, and address.";
      }

      case "add_to_cart": {
        const { rows: prodRows } = await pool.query('SELECT id, product_name, price FROM products WHERE id = $1', [toolArgs.product_id]);
        if (prodRows.length === 0) return "Product not found.";

        const product = prodRows[0];
        const quantity = toolArgs.quantity || 1;

        const { rows: sessRows } = await pool.query('SELECT cart FROM v3_sessions WHERE chat_id = $1', [chatId]);
        let cart = sessRows.length > 0 ? sessRows[0].cart : [];
        if (!Array.isArray(cart)) cart = [];

        const existingIdx = cart.findIndex(item => item.product_id === product.id);
        if (existingIdx >= 0) {
          cart[existingIdx].quantity += quantity;
        } else {
          cart.push({ product_id: product.id, product_name: product.product_name, price: product.price, quantity: quantity });
        }

        await pool.query(
          `INSERT INTO v3_sessions (chat_id, cart, last_seen_at) VALUES ($1, $2, NOW())
           ON CONFLICT (chat_id) DO UPDATE SET cart = $2, last_seen_at = NOW()`,
          [chatId, JSON.stringify(cart)]
        );

        return `✅ *${product.product_name}* added to cart!\n\nQty: ${quantity} × Rs. ${product.price}\n\nNeed more or ready to checkout?`;
      }

      case "remove_from_cart": {
        const { rows } = await pool.query('SELECT cart FROM v3_sessions WHERE chat_id = $1', [chatId]);
        let cart = rows.length > 0 ? rows[0].cart : [];
        const originalLength = cart.length;
        cart = cart.filter(item => item.product_id !== toolArgs.product_id);

        if (cart.length === originalLength) return "Product not in cart.";

        await pool.query('UPDATE v3_sessions SET cart = $1 WHERE chat_id = $2', [JSON.stringify(cart), chatId]);
        return "✅ Product removed.\n\nView *cart* or continue shopping?";
      }

      case "clear_cart": {
        await pool.query('UPDATE v3_sessions SET cart = $1 WHERE chat_id = $2', ['[]', chatId]);
        return "🗑️ Cart cleared. Search for new products!";
      }

      case "checkout": {
        const { rows: cartRows } = await pool.query('SELECT cart FROM v3_sessions WHERE chat_id = $1', [chatId]);
        const cart = cartRows.length > 0 ? cartRows[0].cart : [];

        if (!Array.isArray(cart) || cart.length === 0) return "Cart is empty! Add products first.";

        let total = 0;
        cart.forEach(item => total += item.price * item.quantity);

        const { rows } = await pool.query(
          `INSERT INTO orders (whatsapp_chat_id, customer_name, phone, address, city, total, items, status, created_at)
           VALUES ($1, $2, $3, $4, $5, $6, $7, 'pending', NOW()) RETURNING id`,
          [chatId, toolArgs.customer_name, toolArgs.phone, toolArgs.address, toolArgs.city, total, JSON.stringify(cart)]
        );

        await pool.query('UPDATE v3_sessions SET cart = $1 WHERE chat_id = $2', ['[]', chatId]);

        return `✅ *Order Confirmed!*\n\nOrder ID: #${rows[0].id}\nTotal: Rs. ${total}\n\nCustomer: ${toolArgs.customer_name}\nPhone: ${toolArgs.phone}\nAddress: ${toolArgs.address}, ${toolArgs.city}\n\nOur team will contact you soon. Thank you! 🎉`;
      }

      case "get_order_status": {
        const phone = toolArgs.phone || chatId;
        const { rows } = await pool.query(
          `SELECT id, status, total, created_at FROM orders 
           WHERE phone = $1 OR whatsapp_chat_id = $2 ORDER BY created_at DESC LIMIT 3`,
          [phone, chatId]
        );

        if (rows.length === 0) return "No orders found. Want to place an order?";

        let result = "📦 *Your Orders:*\n\n";
        rows.forEach((o, i) => {
          result += `${i+1}. Order #${o.id}\n   Status: ${o.status}\n   Total: Rs. ${o.total}\n   Date: ${new Date(o.created_at).toLocaleDateString('en-PK')}\n\n`;
        });
        return result;
      }

      case "start_quotation": {
        await pool.query(
          `INSERT INTO v3_sessions (chat_id, quote_state, last_seen_at) VALUES ($1, '{"step":"started"}', NOW())
           ON CONFLICT (chat_id) DO UPDATE SET quote_state = '{"step":"started"}', last_seen_at = NOW()`,
          [chatId]
        );
        return `🏠 *Smart Home Installation Quote*\n\nTo provide an accurate quote, I need:\n\n1. House size (in marlas)?\n2. Number of stories/floors?\n3. How many rooms need automation?\n\nPlease share these details.`;
      }

      case "get_company_info": {
        const info = {
          location: "📍 *Location:* Okara, Punjab, Pakistan\n\nWe serve: Lahore, Islamabad, Multan, Faisalabad, Sahiwal",
          contact: "📞 *Contact:*\nWhatsApp: (Active)\nWebsite: waltonmarket.xyz",
          payment: "💳 *Payment Methods:*\n1. Cash on Delivery\n2. Bank Transfer (5% discount)\n\nBank details shared after order confirmation.",
          delivery: "🚚 *Delivery:*\nFree delivery in Punjab cities\n2-3 business days\nTracking provided",
          all: "📋 *WaltonMarket Info*\n\n📍 Okara, Punjab\n📞 WhatsApp Active\n💳 COD / Bank Transfer\n🚚 Free delivery in Punjab"
        };
        return info[toolArgs.info_type] || info.all;
      }

      case "escalate_to_human": {
        await pool.query(
          `INSERT INTO v3_sessions (chat_id, escalated_at, last_seen_at) VALUES ($1, NOW(), NOW())
           ON CONFLICT (chat_id) DO UPDATE SET escalated_at = NOW()`,
          [chatId]
        );
        return "👤 Connecting you to human support.\n\nOur team will respond shortly.";
      }

      default:
        return `Tool "${toolName}" is not available yet.`;
    }
  } catch (err) {
    console.error(`Tool error [${toolName}]:`, err);
    return `Sorry, technical issue. Please try again.`;
  }
}

// ═══ MENU PRE-PROCESSOR ═══
// Intercept single-digit menu selections BEFORE calling Gemini
// This handles the most common failure: Gemini treating "3" as a search query
const userMsg = workflowState.userMessage.trim();

if (/^[1-4]$/.test(userMsg)) {
  // Check if recent conversation contains a menu
  const recentTexts = workflowState.contents
    .slice(-6)
    .map(c => (c.parts || []).map(p => p.text || (p.functionResponse?.response?.result) || '').join(''))
    .join('');

  const isMenuContext = recentTexts.includes('1️⃣') && recentTexts.includes('View Catalogue');

  if (isMenuContext) {
    const menuToolMap = {
      '1': { name: 'search_products', args: { query: '' } },
      '2': { name: 'get_order_status', args: {} },
      '3': { name: 'start_quotation', args: {} },
      '4': { name: 'escalate_to_human', args: {} }
    };

    const directTool = menuToolMap[userMsg];
    const toolResult = await executeTool(directTool.name, directTool.args, workflowState.chatId);

    workflowState.contents.push({
      role: "model",
      parts: [{ functionCall: { name: directTool.name, args: directTool.args } }]
    });

    workflowState.contents.push({
      role: "user",
      parts: [{ functionResponse: { name: directTool.name, response: { result: toolResult } } }]
    });

    workflowState.iteration++;
    return [{ json: workflowState }];
  }
}

// ═══ CALL GEMINI WITH RETRY ═══
let response;
let attempts = 0;
const maxAttempts = 4;

while (attempts < maxAttempts) {
  try {
    response = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent',
      headers: { 'Content-Type': 'application/json' },
      qs: { key: GEMINI_API_KEY },
      body: {
        contents: workflowState.contents,
        tools,
        systemInstruction: { parts: [{ text: systemInstruction }] },
        generationConfig: { temperature: 0.2 }
      },
      timeout: 25000
    });
    break;
  } catch (err) {
    attempts++;
    const statusCode = err.response?.status || err.statusCode || 0;
    const isRetryable = (statusCode >= 500 && statusCode < 600) || statusCode === 429 || err.code === 'ETIMEDOUT';

    if (isRetryable && attempts < maxAttempts) {
      await new Promise(r => setTimeout(r, Math.min(1000 * Math.pow(2, attempts), 8000)));
      continue;
    }

    return [{
      json: {
        mode: 'FINAL_REPLY',
        ...workflowState,
        reply: "I'm experiencing technical difficulties. Please try again in a moment."
      }
    }];
  }
}

// ═══ HANDLE RESPONSE ═══
const parts = response.candidates?.[0]?.content?.parts || [];
const functionCalls = parts.filter(p => p.functionCall).map(p => p.functionCall);
const textParts = parts.filter(p => p.text).map(p => p.text);

if (functionCalls.length === 0 && textParts.length > 0) {
  return [{
    json: {
      mode: 'FINAL_REPLY',
      ...workflowState,
      reply: textParts.join('\n')
    }
  }];
}

if (functionCalls.length > 0) {
  const toolCall = functionCalls[0];
  const toolResult = await executeTool(toolCall.name, toolCall.args || {}, workflowState.chatId);

  workflowState.contents.push({
    role: "model",
    parts: [{ functionCall: { name: toolCall.name, args: toolCall.args } }]
  });

  workflowState.contents.push({
    role: "user",
    parts: [{ functionResponse: { name: toolCall.name, response: { result: toolResult } } }]
  });

  workflowState.iteration++;
  return [{ json: workflowState }];
}

return [{
  json: {
    mode: 'FINAL_REPLY',
    ...workflowState,
    reply: "Sorry, I got confused. Type *menu* for options."
  }
}];

