INSERT INTO v3_conversation_history (chat_id, role, content) VALUES 
  ('{{ $json.chatId }}', 'user', $${{ $json.userMessage }}$$),
  ('{{ $json.chatId }}', 'model', $${{ $json.reply }}$$);
